// Delete off-topic blog drafts generated by the (now-disabled) disease-based content
// cron: they have a diseaseCluster set and NO sourceMissionId (i.e. not tied to a
// task the doctor actually worked on). Only DRAFTS are touched — published pages and
// task-linked content are never deleted.
//   node scripts/cleanup-disease-cron-blogs.mjs          # dry run
//   node scripts/cleanup-disease-cron-blogs.mjs --apply  # delete
import mongoose from 'mongoose';
const APPLY = process.argv.includes('--apply');
await mongoose.connect(process.env.MONGODB_URI);
const db = mongoose.connection;
const blogs = db.collection('blogarticles');
const doctors = db.collection('doctors');
const filter = { diseaseCluster: { $nin: ['', null] }, $or: [{ sourceMissionId: { $exists: false } }, { sourceMissionId: null }] };
const all = await blogs.find(filter).project({ doctorId:1, title:1, status:1, diseaseCluster:1 }).toArray();
const byStatus = {}; for (const b of all) byStatus[b.status||'(none)'] = (byStatus[b.status||'(none)']||0)+1;
console.log(`Matched disease-cron blogs: ${all.length}`); console.log('  by status:', JSON.stringify(byStatus));
const drafts = all.filter(b => (b.status||'draft') === 'draft');
console.log(`\nDRAFTS to delete: ${drafts.length} (published are left untouched)`);
const byDoc = {}; for (const b of drafts) { const k=String(b.doctorId); byDoc[k]=(byDoc[k]||0)+1; }
for (const [id,n] of Object.entries(byDoc)) { const d = await doctors.findOne({_id:new mongoose.Types.ObjectId(id)},{projection:{displayName:1,name:1,email:1}}); console.log(`  ${d?.displayName||d?.name||d?.email||id}: ${n}`); }
if (APPLY && drafts.length) {
  const res = await blogs.deleteMany({ ...filter, $and: [{ $or: [{ status: 'draft' }, { status: { $exists: false } }] }] });
  console.log(`\nApplied. Deleted ${res.deletedCount}.`);
} else if (!APPLY) { console.log('\nDry run — re-run with --apply to delete.'); }
await mongoose.disconnect();
